<?php
require dirname(__DIR__).'/src/bootstrap.php';
require dirname(__DIR__).'/src/layout.php';
require_roles(['owner','administrator']);
$error='';$notice='';$selectedId=(int)($_GET['lead']??0);
$statuses=['new'=>'New','contacted'=>'Contacted','qualified'=>'Qualified','proposal_sent'=>'Proposal sent','negotiation'=>'Negotiation','won'=>'Won','lost'=>'Lost'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='create'){
  $name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone']??''));$org=trim((string)($_POST['organisation']??''));$subject=trim((string)($_POST['subject']??''));$message=trim((string)($_POST['message']??''));$product=(int)($_POST['product_id']??0);
  if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$subject===''||strlen($name)>160||strlen($email)>190||strlen($phone)>60||strlen($org)>190||strlen($subject)>240||strlen($message)>10000){$error='Complete the lead name, valid email and subject. Check field lengths.';}
  else{$productId=$product>0?$product:null;$source='admin';$stmt=db()->prepare("INSERT INTO platform_leads(name,email,phone,organisation,product_id,source,subject,message) VALUES(?,?,?,?,?,?,?,?)");$stmt->bind_param('ssssisss',$name,$email,$phone,$org,$productId,$source,$subject,$message);$stmt->execute();$selectedId=(int)db()->insert_id;audit_event('lead.created','lead',$selectedId);redirect('leads.php?lead='.$selectedId.'&saved=1');}
 }elseif($action==='update'){
  $id=(int)($_POST['lead_id']??0);$status=(string)($_POST['status']??'new');$priority=(string)($_POST['priority']??'normal');$assignedRaw=trim((string)($_POST['assigned_admin_id']??''));$assigned=$assignedRaw===''?null:(int)$assignedRaw;$follow=trim((string)($_POST['next_follow_up']??''));$value=trim((string)($_POST['estimated_value']??''));$lost=trim((string)($_POST['lost_reason']??''));
  if($id<1||!isset($statuses[$status])||!in_array($priority,['low','normal','high'],true)||($assignedRaw!==''&&!ctype_digit($assignedRaw))||($value!==''&&!preg_match('/^\d{1,12}(\.\d{1,2})?$/',$value))||strlen($lost)>500){$error='Check lead status, assignment, value and follow-up details.';}
  else{$followDb=$follow!==''?str_replace('T',' ',$follow).':00':null;$valueDb=$value!==''?(float)$value:null;$stmt=db()->prepare('UPDATE platform_leads SET status=?,priority=?,assigned_admin_id=?,next_follow_up=?,estimated_value=?,lost_reason=? WHERE id=?');$stmt->bind_param('ssisdsi',$status,$priority,$assigned,$followDb,$valueDb,$lost,$id);$stmt->execute();audit_event('lead.updated','lead',$id,['status'=>$status]);$selectedId=$id;redirect('leads.php?lead='.$id.'&saved=1');}
 }elseif($action==='activity'){
  $id=(int)($_POST['lead_id']??0);$type=(string)($_POST['activity_type']??'note');$subject=trim((string)($_POST['activity_subject']??''));$details=trim((string)($_POST['details']??''));$follow=trim((string)($_POST['activity_follow_up']??''));
  if($id<1||!in_array($type,['note','call','email','meeting','status_change','follow_up'],true)||$subject===''||strlen($subject)>240||strlen($details)>10000){$error='Enter a valid activity subject and details.';}
  else{$adminId=(int)current_admin()['id'];$followDb=$follow!==''?str_replace('T',' ',$follow).':00':null;$stmt=db()->prepare('INSERT INTO platform_lead_activities(lead_id,admin_user_id,activity_type,subject,details,follow_up_at) VALUES(?,?,?,?,?,?)');$stmt->bind_param('iissss',$id,$adminId,$type,$subject,$details,$followDb);$stmt->execute();if($followDb){$u=db()->prepare('UPDATE platform_leads SET next_follow_up=? WHERE id=?');$u->bind_param('si',$followDb,$id);$u->execute();}audit_event('lead.activity_added','lead',$id,['type'=>$type]);$selectedId=$id;redirect('leads.php?lead='.$id.'&saved=1');}
 }
}
if(isset($_GET['saved']))$notice='Lead details have been saved.';
$admins=db()->query("SELECT id,display_name FROM admin_users WHERE is_active=1 ORDER BY display_name");
$products=db()->query("SELECT id,name FROM platform_products WHERE status='published' ORDER BY name");
$filter=(string)($_GET['status']??'');if(isset($statuses[$filter])){$st=db()->prepare('SELECT l.*,p.name AS product_name,a.display_name AS assigned_name FROM platform_leads l LEFT JOIN platform_products p ON p.id=l.product_id LEFT JOIN admin_users a ON a.id=l.assigned_admin_id WHERE l.status=? ORDER BY COALESCE(l.next_follow_up,l.created_at) ASC LIMIT 300');$st->bind_param('s',$filter);$st->execute();$list=$st->get_result();}else{$list=db()->query('SELECT l.*,p.name AS product_name,a.display_name AS assigned_name FROM platform_leads l LEFT JOIN platform_products p ON p.id=l.product_id LEFT JOIN admin_users a ON a.id=l.assigned_admin_id ORDER BY CASE WHEN l.next_follow_up IS NULL THEN 1 ELSE 0 END,l.next_follow_up ASC,l.created_at DESC LIMIT 300');}
$selected=null;$activities=null;$proposals=null;
if($selectedId>0){$st=db()->prepare('SELECT l.*,p.name AS product_name,a.display_name AS assigned_name FROM platform_leads l LEFT JOIN platform_products p ON p.id=l.product_id LEFT JOIN admin_users a ON a.id=l.assigned_admin_id WHERE l.id=?');$st->bind_param('i',$selectedId);$st->execute();$selected=$st->get_result()->fetch_assoc();if($selected){$st=db()->prepare('SELECT x.*,a.display_name FROM platform_lead_activities x LEFT JOIN admin_users a ON a.id=x.admin_user_id WHERE x.lead_id=? ORDER BY x.created_at DESC');$st->bind_param('i',$selectedId);$st->execute();$activities=$st->get_result();$st=db()->prepare('SELECT id,proposal_number,title,status,total_amount,currency,created_at FROM platform_proposals WHERE lead_id=? ORDER BY created_at DESC');$st->bind_param('i',$selectedId);$st->execute();$proposals=$st->get_result();}}
page_header('Sales leads');
?>
<div class="eyebrow">Sales pipeline</div><h1 class="heading">Leads</h1><p class="sub">Capture prospects, record calls and emails, assign follow-ups and monitor opportunities through to a decision.</p>
<?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?>
<div class="panel"><h2>Add a lead</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="form-grid"><div><label>Name</label><input name="name" maxlength="160" required></div><div><label>Email</label><input name="email" type="email" maxlength="190" required></div><div><label>Phone / WhatsApp</label><input name="phone" maxlength="60"></div><div><label>Organisation</label><input name="organisation" maxlength="190"></div><div><label>Product interest</label><select name="product_id"><option value="0">Not specified</option><?php while($p=$products->fetch_assoc()):?><option value="<?=(int)$p['id']?>"><?=e($p['name'])?></option><?php endwhile;?></select></div><div><label>Enquiry subject</label><input name="subject" maxlength="240" required></div><div class="wide"><label>Requirements / notes</label><textarea name="message" rows="3" maxlength="10000"></textarea></div></div><button class="btn" type="submit">Create lead</button></form></div>
<div class="panel"><h2>Lead pipeline</h2><p class="label"><?php foreach($statuses as $key=>$label):?><a href="leads.php?status=<?=e($key)?>" style="margin-right:12px"><?=e($label)?></a><?php endforeach;?> <a href="leads.php">All leads</a></p><table><thead><tr><th>Lead</th><th>Product</th><th>Status</th><th>Follow-up</th><th>Assigned</th><th></th></tr></thead><tbody><?php if($list->num_rows):while($l=$list->fetch_assoc()):?><tr><td><strong><?=e($l['name'])?></strong><br><span class="label"><?=e($l['email'])?> · <?=e($l['organisation'])?></span></td><td><?=e($l['product_name']??'—')?></td><td><?=e($statuses[$l['status']]??$l['status'])?></td><td><?=e($l['next_follow_up']??'—')?></td><td><?=e($l['assigned_name']??'Unassigned')?></td><td><a class="btn secondary" href="leads.php?lead=<?=(int)$l['id']?>">Open</a></td></tr><?php endwhile;else:?><tr><td colspan="6" class="empty">No leads yet. Website proposal requests will appear here after migration 010 is installed.</td></tr><?php endif;?></tbody></table></div>
<?php if($selected):?><div class="panel"><h2>Lead #<?=(int)$selected['id']?> · <?=e($selected['name'])?></h2><p><?=e($selected['email'])?> · <?=e($selected['phone'])?> · <?=e($selected['organisation'])?></p><p><?=nl2br(e($selected['message']))?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="lead_id" value="<?=(int)$selected['id']?>"><div class="form-grid"><div><label>Status</label><select name="status"><?php foreach($statuses as $k=>$v):?><option value="<?=e($k)?>" <?=$selected['status']===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div><label>Priority</label><select name="priority"><?php foreach(['low','normal','high'] as $v):?><option value="<?=$v?>" <?=$selected['priority']===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></div><div><label>Assign to</label><select name="assigned_admin_id"><option value="">Unassigned</option><?php $admins->data_seek(0);while($a=$admins->fetch_assoc()):?><option value="<?=(int)$a['id']?>" <?=(int)$selected['assigned_admin_id']===(int)$a['id']?'selected':''?>><?=e($a['display_name'])?></option><?php endwhile;?></select></div><div><label>Next follow-up</label><input type="datetime-local" name="next_follow_up" value="<?=e($selected['next_follow_up']?date('Y-m-d\TH:i',strtotime($selected['next_follow_up'])):'')?>"></div><div><label>Estimated opportunity value (KES)</label><input name="estimated_value" inputmode="decimal" value="<?=e($selected['estimated_value']??'')?>"></div><div><label>Reason lost (if applicable)</label><input name="lost_reason" maxlength="500" value="<?=e($selected['lost_reason']??'')?>"></div></div><button class="btn" type="submit">Update lead</button><a class="btn secondary" href="proposal-create.php?lead=<?=(int)$selected['id']?>">Prepare proposal</a></form>
<div class="panel"><h2>Record an activity</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="activity"><input type="hidden" name="lead_id" value="<?=(int)$selected['id']?>"><div class="form-grid"><div><label>Activity type</label><select name="activity_type"><?php foreach(['note','call','email','meeting','follow_up'] as $v):?><option value="<?=$v?>"><?=ucfirst(str_replace('_',' ',$v))?></option><?php endforeach;?></select></div><div><label>Subject</label><input name="activity_subject" maxlength="240" required></div><div class="wide"><label>Details</label><textarea name="details" rows="3" maxlength="10000"></textarea></div><div><label>Follow-up date (optional)</label><input type="datetime-local" name="activity_follow_up"></div></div><button class="btn" type="submit">Save activity</button></form></div>
<div class="panel"><h2>Activity history</h2><?php if($activities&&$activities->num_rows):while($a=$activities->fetch_assoc()):?><p><strong><?=e(ucfirst(str_replace('_',' ',$a['activity_type'])))?>: <?=e($a['subject'])?></strong> <span class="label">· <?=e($a['created_at'])?> · <?=e($a['display_name']??'System')?></span><br><?=nl2br(e($a['details']))?></p><hr><?php endwhile;else:?><p class="empty">No activities recorded.</p><?php endif;?></div>
<div class="panel"><h2>Proposals</h2><?php if($proposals&&$proposals->num_rows):while($p=$proposals->fetch_assoc()):?><p><a href="proposal.php?id=<?=(int)$p['id']?>"><?=e($p['proposal_number'])?> · <?=e($p['title'])?></a> — <?=e($p['status'])?> — <?=e($p['currency'])?> <?=number_format((float)$p['total_amount'],2)?></p><?php endwhile;else:?><p class="empty">No proposals created for this lead.</p><?php endif;?></div></div><?php endif;?>
<?php page_footer(); ?>
